def set_rules(self: "MinecraftOsrWorld") -> None:    multiworld = self.multiworld    player = self.player    rules_lookup = get_rules_lookup(self, player)    # Set entrance rules    for entrance_name, rule in rules_lookup["entrances"].items():        multiworld.get_entrance(entrance_name, player).access_rule = rule    # Set location rules    for location_name, rule in rules_lookup["locations"].items():        multiworld.get_location(location_name, player).access_rule = rule    def location_count(state: CollectionState) -> int:        return len([location for location in multiworld.get_locations(player) if                    location.address is not None and                    location.can_reach(state)])    # Retrieve the selected quest goal    quest_goal = self.options.quest_goal.value    # Mapping QuestGoal choices to FTB Quest locations and item keys    quest_mapping = {        0: "18E8E67F431E99E4:Simple Achievements:1794937885768456676",        1: "46F450DDEAECE702:minecraft:dragon_egg:5112800391031744258",        2: "0B4FE52E8C83C177:constructionwand:infinity_wand:815122045666050423",        3: "69912119C98D6247:Conquor the Twilight:7606897640244863559",        4: "79E30F3A54F84EA4:botania:gaia_ingot:8782880441510678180",        5: "187CE1DC0DC4AF2D:bigreactors:insanite_block:1764533489262440237",        6: "2F89C9A81F049F60:betterfurnacesreforged:ultimate_forge:3425490715504058208",        7: "4A3ED57B133E0F5C:ad_astra:tier_4_rocket:5349948131943255900",        8: "46DCFABCE6CA89BC:projectexpansion:transmutation_interface:5106231766764128700",        9: "2218FD98BD04A52E:draconicevolution:chaos_shard:2456992429178660142",        10: "725C86A23081A0F6:avaritia:infinity_ingot:8240609449337790710",        11: "030AD281CFAFB320:Infinity Tools:219218986857902880",        12: "51F3D3ABAD3D00CC:Infinity Armor:5905296270712176844"    }    goal_location = quest_mapping.get(quest_goal,    "18E8E67F431E99E4:Simple Achievements:1794937885768456676")    def completed_goal_quest(state: CollectionState):        if goal_location == quest_mapping[0]:            total_locations = len([                location for location in multiworld.get_locations(player)                if location.address is not None            ])            completed_locations = len([                location for location in multiworld.get_locations(player)                if location.address is not None and location.can_reach(state)            ])            return completed_locations == total_locations        return state.can_reach_location(goal_location, player)    multiworld.completion_condition[player] = lambda state: completed_goal_quest(state)    # Set exclusions on hard/unreasonable/postgame    excluded_advancements = set()    if not self.options.quest_goal == QuestGoal.option_dragon_egg:        excluded_advancements.update(Constants.exclusion_info["dragon_egg"])    if not self.options.quest_goal == QuestGoal.option_infinity_wand:        excluded_advancements.update(Constants.exclusion_info["infinity_wand"])    if not self.options.quest_goal == QuestGoal.option_conquor_the_twilight:        excluded_advancements.update(Constants.exclusion_info["conquor_the_twilight"])    if not self.options.quest_goal == QuestGoal.option_gaia_spirit_ingot:            excluded_advancements.update(Constants.exclusion_info["gaia_ingot"])    if not self.options.quest_goal == QuestGoal.option_insanite_block:            excluded_advancements.update(Constants.exclusion_info["insanite_block"])    if not self.options.quest_goal == QuestGoal.option_ultimate_forge:            excluded_advancements.update(Constants.exclusion_info["ultimate_forge"])    if not self.options.quest_goal == QuestGoal.option_tier_4_rocket:            excluded_advancements.update(Constants.exclusion_info["tier_4_rocket"])    if not self.options.quest_goal == QuestGoal.option_transmutation_interface:            excluded_advancements.update(Constants.exclusion_info["transmutation_interface"])    if not self.options.quest_goal == QuestGoal.option_chaos_shard:            excluded_advancements.update(Constants.exclusion_info["chaos_shard"])    if not self.options.quest_goal == QuestGoal.option_infinity_ingot:            excluded_advancements.update(Constants.exclusion_info["infinity_ingot"])    if not self.options.quest_goal == QuestGoal.option_infinity_tools:            excluded_advancements.update(Constants.exclusion_info["infinity_tools"])    if not self.options.quest_goal == QuestGoal.option_infinity_armor:            excluded_advancements.update(Constants.exclusion_info["infinity_armor"])    exclusion_rules(multiworld, player, excluded_advancements)